#include "test_common.h"
#include "hospital_management.h"
static BmsHospital_t hosp(uint32_t id,const char*n){BmsHospital_t h;memset(&h,0,sizeof h);h.hospitalId=id;snprintf(h.name,sizeof h,"%s",n);snprintf(h.location,sizeof h,"Chennai");snprintf(h.address,sizeof h,"Address");snprintf(h.contactNumber,sizeof h,"9876543210");snprintf(h.email,sizeof h,"h%u@test.com",id);h.isActive=true;return h;}
static void test_crud_routes(void){BmsHospitalContext_t c;BmsHospital_t a=hosp(1,"A Hospital"),b=hosp(2,"B Hospital"),out;uint32_t km=0;ASSERT_OK(HospitalManagementInitialize(&c));ASSERT_OK(HospitalManagementAdd(&c,&a));ASSERT_OK(HospitalManagementAdd(&c,&b));ASSERT_STATUS(BMS_STATUS_ALREADY_EXISTS,HospitalManagementAdd(&c,&a));ASSERT_OK(HospitalManagementSearchById(&c,1,&out));snprintf(a.location,sizeof a,"Updated");ASSERT_OK(HospitalManagementUpdate(&c,&a));ASSERT_OK(HospitalManagementAddRoute(&c,1,2,12));ASSERT_OK(HospitalManagementGetRouteDistance(&c,1,2,&km));CU_ASSERT_EQUAL(km,12U);ASSERT_OK(HospitalManagementFindNearest(&c,1,&out,&km));CU_ASSERT_EQUAL(out.hospitalId,2U);ASSERT_OK(HospitalManagementDelete(&c,2));HospitalManagementDeinitialize(&c);}
void RegisterHospitalTests(void){CU_pSuite s=CU_add_suite("Hospital",NULL,NULL);CU_add_test(s,"CRUD routes nearest",test_crud_routes);}
